components.css:
.ds-contact { position: relative; display: inline-block; font-family: var(--font-display, "Bricolage Grotesque", Archivo, system-ui, sans-serif); font-weight: 800; font-size: 36px; line-height: 38px; letter-spacing: -0.01em; color: var(--ink, #0b0b0b); text-decoration: none; padding-bottom: 4px; transition: color 0.18s ease-out; }
.ds-contact::before { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: currentColor; }
.ds-contact::after { content: attr(data-imprint); position: absolute; left: 0; top: calc(100% + 8px); font-family: var(--font-apparatus, "Redaction 20", Archivo, system-ui, sans-serif); font-size: 13px; font-weight: 400; line-height: 1.35; letter-spacing: normal; text-transform: none; color: var(--ink, #0b0b0b); opacity: 0; transition: opacity 0.18s ease-out; pointer-events: none; white-space: nowrap; }
.ds-contact:hover, .ds-contact:focus-visible { color: var(--blue-deep, #1b3a8f); }
.ds-contact:hover::after, .ds-contact:focus-visible::after { opacity: 0.75; }

.ds-running-head { display: flex; align-items: center; justify-content: space-between; padding: 8px 0; border-top: 2px solid var(--ink, #0b0b0b); }
.ds-running-head__no { font-family: var(--font-apparatus, "Redaction 20", Archivo, system-ui, sans-serif); font-size: 13px; line-height: 1.35; letter-spacing: 0.1em; color: var(--ink, #0b0b0b); }
.ds-running-head__chip { width: 12px; height: 12px; background: var(--pink, #fb79b1); }

.ds-proj { display: flex; flex-direction: column; text-decoration: none; color: inherit; border-top: 2px solid var(--ink, #0b0b0b); }
.ds-proj__field { display: block; aspect-ratio: 2.6 / 1; border-bottom: 2px solid var(--ink, #0b0b0b); background-color: color-mix(in srgb, var(--pink, #fb79b1) 26%, var(--paper, #f6f0e2)); }
.ds-proj__title { position: relative; isolation: isolate; font-family: var(--font-display, "Bricolage Grotesque", Archivo, system-ui, sans-serif); font-weight: 800; font-size: 28px; line-height: 32px; letter-spacing: -0.012em; margin: 24px 0 8px; color: var(--ink, #0b0b0b); transition: color 0.2s ease; }
.ds-proj__title::before, .ds-proj__title::after { content: attr(data-title); position: absolute; inset: 0; z-index: -1; pointer-events: none; mix-blend-mode: multiply; opacity: 0.5; transition: transform 0.45s cubic-bezier(0.16, 1, 0.3, 1); }
.ds-proj__title::before { color: var(--pink, #fb79b1); transform: translate(-0.7px, 0.55px); }
.ds-proj__title::after { color: var(--blue, #5285e3); transform: translate(0.55px, -0.45px); }
.ds-proj__body { font-family: var(--font-text, Archivo, system-ui, -apple-system, sans-serif); font-size: 14px; line-height: 20px; max-width: 66ch; margin: 0 0 24px; opacity: 0.88; color: var(--ink, #0b0b0b); }
.ds-proj__tags { display: flex; flex-wrap: wrap; gap: 6px; }
.ds-proj:hover .ds-proj__title { color: var(--blue-deep, #1b3a8f); }
.ds-proj:hover .ds-proj__title::before { transform: translate(-1.4px, 1.1px); }
.ds-proj:hover .ds-proj__title::after { transform: translate(1.1px, -0.9px); }
.ds-proj__tag { display: inline-flex; align-items: center; border: 1px solid var(--rule-strong, rgba(11,11,11,0.55)); padding: 4px 9px; border-radius: 0; font-family: var(--font-display, "Bricolage Grotesque", Archivo, system-ui, sans-serif); font-weight: 600; font-size: 11px; line-height: 24px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--ink, #0b0b0b); }

.ds-colourbar { display: inline-flex; flex-direction: column; gap: 6px; }
.ds-colourbar__chip { width: 11px; height: 11px; }
.ds-colourbar__chip--pink { background: var(--pink, #fb79b1); }
.ds-colourbar__chip--blue { background: var(--blue, #5285e3); }
.ds-colourbar__chip--yellow { background: var(--yellow, #f6ce5c); }

.ds-masthead { display: block; width: 100%; height: auto; overflow: visible; }
.ds-masthead text { font-family: var(--font-display, "Bricolage Grotesque", Archivo, system-ui, sans-serif); font-weight: 800; }
.ds-masthead__pink { fill: var(--pink, #fb79b1); mix-blend-mode: multiply; transform: translate(-6.5px, 4.1px); }
.ds-masthead__blue { fill: var(--blue, #5285e3); mix-blend-mode: multiply; transform: translate(3.2px, -5.6px); }
.ds-masthead__key { fill: var(--ink, #0b0b0b); mix-blend-mode: multiply; opacity: 0.86; transform: translate(0.7px, 0.5px); }
